const FAQ_WORD_COUNT = NZ_GCC_EXPORT_FAQ.reduce(
  (sum, item) => sum + countWords(item.question) + countWords(item.answer),
  0,
);

/** Article words: summary + narrative + FAQ. The bibliography is excluded from the band. */
export const NZ_GCC_EXPORT_WORD_COUNT =
  countWords(NZ_GCC_EXPORT_EXECUTIVE_SUMMARY_HTML) + countWords(NARRATIVE_HTML) + FAQ_WORD_COUNT;

const READING_WORDS_PER_MINUTE = 225;

export const NZ_GCC_EXPORT_READING_TIME = Math.ceil(
  (countWords(NZ_GCC_EXPORT_EXECUTIVE_SUMMARY_HTML) + countWords(NARRATIVE_HTML) + FAQ_WORD_COUNT) /
    READING_WORDS_PER_MINUTE,
);

